package qa.architecture;
import application.save.*; import domain.economy.*; import domain.inventory.item.firearms.*; import domain.inventory.item.throwingWeapons.*; import domain.save.*; import domain.persona.*; import domain.character.*; import domain.character.progression.*; import domain.character.sheet.*; import domain.inventory.*; import java.nio.file.*; import java.util.*;
public final class ArchitectureIntegrityVerification {@org.junit.jupiter.api.Test
    @org.junit.jupiter.api.Tag("architecture")
        void verifiesCanonicalContract() throws Exception{var p=FirearmCatalog.repeatingPneumaticRifleV881();org.junit.jupiter.api.Assertions.assertTrue(p.reloadDurationSeconds()==6.0&&p.pressureStepDurationSeconds()==0.55,"Neumático");org.junit.jupiter.api.Assertions.assertTrue(Math.abs(FirearmCatalog.submachineGunV881().shotIntervalSeconds()-0.12)<1e-9,"SMG 500 RPM");org.junit.jupiter.api.Assertions.assertTrue(ThrowingCadencePolicy.intervalSeconds(ThrowingWeaponCatalog.throwingKnifeV881())==0.5,"Cuchillo");org.junit.jupiter.api.Assertions.assertTrue(IntellectualAppraisalCatalog.requiredNames().contains("Carcaj para flechas"),"Carcaj tasable");org.junit.jupiter.api.Assertions.assertTrue(IntellectualAppraisalCatalog.requiredNames().stream().noneMatch(x->x.contains("Mucus")),"Mucus excluido");roundTrip();}
private static void roundTrip()throws Exception{var sh=CharacterSheet.kenanCanonical();var inv=InventoryState.emptyWithoutPersonalTransport();var st=new DerivedStatisticsCalculator().calculate(sh,Gender.HOMBRE,inv,domain.environment.time.DayPhase.DAY);var g=new GameSessionState(new CharacterDefinition(CharacterIdentity.kenanCanonical()),new CharacterTitle("Guerrero de Ébano"),new CharacterProgressionState(88,sh,MucusWallet.of(1,2,0,0,0,0)),st,inv);g.vitalResources().setCurrentHealth(Math.min(5,g.vitalResources().maximumHealth()));var persona=new PersonaProfile("kenan","Kenan",Gender.HOMBRE,CharacterClass.INDOMITO,88,List.of(),List.of());Path d=Files.createTempDirectory("m492-");try{var repo=new infrastructure.save.LocalJsonSaveRepository(d);var svc=new GameSaveService(repo);var slot=svc.saveQuick(persona.id(),GameSnapshotFactory.from(g,persona));var loaded=new GameLoadService(repo).load(slot);org.junit.jupiter.api.Assertions.assertTrue(loaded.game().level()==88&&loaded.game().progression().mucusWallet().quantityOf(MucusType.BLANCO)==1,"Round-trip save/hydrate");}finally{try(var w=Files.walk(d)){w.sorted(Comparator.reverseOrder()).forEach(x->{try{Files.deleteIfExists(x);}catch(Exception ignored){}});}}}
}
